/*nini❀樱花*/
/*仅发布于discord旅程社区，故意从其他途径获取的参考下一条*/
/*绝对禁止二传商用二改，否则你全家会在天上失望的等着你飞*/
/*部分代码来自于旅程美化教程贴中热心老师的分享，已在相应内容后标注来源*/
/*素材来源：网络搜索/望江寻路/雪时/Aa零眦/无敌枝笺/破烂大王/無鸦泗泾/累点很低*/
/*主页头像画师：冼月*/
/*自定义文字、头像图片调整在字体后↓*/
/*欢迎页头像文字更改、预设转移插件适配在最后*/
/*字体*/
@import url("https://fontsapi.zeoseven.com/954/main/result.css");
@import url("https://fontsapi.zeoseven.com/72/main/result.css");
@import url("https://fontsapi.zeoseven.com/256/main/result.css");
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}
/*自定义文字*/
.mes .mes_block::before {
    content: "- 清绝·影也别˚知心惟有月" ;
    position: absolute ;
    top: -63px ;
    left: 60% ; 
    transform: translateX(-50%) ; 
    white-space: nowrap ;
    font-family: "Huiwen-mincho" !important;/*字体*/
    font-size: 10px ;/*大小*/
    font-style: italic;/*斜体*/
    color: rgba(222, 166, 193, 1) ;/*颜色*/
    line-height: 1 !important; 
    display: block !important; 
}

/* ♪char头像图片位置 */
.mes:not([is_user="true"]) .avatar img {
    object-position: center 20% ; 
}

/* ♪user头像图片位置 */
.mes[is_user="true"] .avatar img {
    object-position: center 10% ; 
}
/* 导航栏&输入框*/
#top-bar {
    background-image: url("https://iili.io/fiTUT6N.png");
    background-size: cover;
    background-repeat: repeat;
    background-position: center bottom;
    border-top: 1px solid rgba(255, 182, 193, 0.3) ;

    box-shadow: inset 0 1px 0 rgba(255, 240, 245, 0.8), inset 0 10px 20px -5px rgba(219, 112, 147, 0.3) ;
    backdrop-filter: blur(5px);
}

#top-settings-holder .drawer-icon::before {
  content: '' ;
  visibility: hidden;
}
#top-settings-holder .drawer {
  flex: 1;
}
#top-settings-holder .drawer-icon {
  display: block;
  margin: 0 auto;
  width: 35px ;
  height: 35px ;
  background-size: 29px ;
  background-position: center ;
  background-repeat: no-repeat ;
  opacity: 0.85 !important;
  transition: all 0.3s ease-in-out;
  filter: drop-shadow(1px 1px 0px rgba(255, 182, 193, 0.6));

}

#top-settings-holder .drawer-icon:not(.closedIcon) {
  opacity: 1;  
  transform: scale(1.08); 
}
/*1*/
#ai-config-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#logo_block .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon,
#table_database_settings_drawer .drawer-icon,#horae_drawer_icon,
#rightNavHolder .drawer-icon {
  background-image: url('https://iili.io/fssSg3l.png');
}

/* 2 */
#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#persona-management-button .drawer-icon {
  background-image: url('https://iili.io/fssSS44.png');

}
/*u*/
#user-settings-button .drawer-icon {
  background-image: url('https://iili.io/fssS8Gf.png') !important;
  background-size: contain !important;
  position: relative;
  z-index: 1;  
  transform: scale(1.25);
  filter: drop-shadow(0px 0px 6px rgba(235, 160, 190, 0.8));
}


@keyframes candyFadeIn {
  0% {
    opacity: 0;
    transform: translateY(-8px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
/*点击*/
#top-settings-holder .drawer-icon:not(.closedIcon) {
    background-image: url('https://iili.io/fbgZifj.png') !important;    
    transform: scale(1);       

}
/* 导航栏下 */ 
/* 分割线 */
#top-settings-holder::after {
    content: '';
    position: absolute;
    bottom: -13px; 
    left: 50%;
    transform: translateX(-50%);
    width: 360px;
    height: 35px;
    background-image: url('https://iili.io/fL5t9oJ.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 10; 
    pointer-events: none; filter: drop-shadow(0px 0px 1px rgba(235, 160, 190, 0.8));
    opacity: 0.8;
}

/* 左右 */
#top-settings-holder::before {
    --icon-url: url('https://iili.io/fb9MpjV.png');  
    content: '';
    position: absolute;
    width: 100%;
    height: 160px;
    pointer-events: none;
    z-index: 100;
    background-image: var(--icon-url), var(--icon-url);
    background-size: 100px;
    background-repeat: no-repeat, no-repeat;
    background-position:
        left -11px top 15px,
        right -9px top 88px;filter: drop-shadow(0px 0px 1px rgba(235, 160, 190, 0.8));
}
/* 输入框 */
#send_form {
    background-image: url("https://iili.io/fiTUT6N.png");
    background-size: cover;
    background-repeat: repeat;
    background-position: center bottom;
    padding: 7px;
    max-width: 720px;
    margin: 0 auto;
    width: 100%;
    position: relative;
    bottom: 0px;
    border-top: 1px solid rgba(255, 182, 193, 0.3);

    box-shadow: inset 0 1px 0 rgba(255, 240, 245, 0.8), inset 0 10px 20px -5px rgba(219, 112, 147, 0.3);
    backdrop-filter: blur(5px);
}

#send_textarea {   
    clip-path: none;

}

/* 装饰线 */
#send_form::before {
    content: '';
    position: absolute;
    top: -17px;
    left: 50%;
    transform: translateX(-50%);
    width: 300px;
    height: 30px;
    background-image: url('https://iili.io/fL5t9oJ.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 10;
    pointer-events: none;
    filter: drop-shadow(0px 0px 0.5px rgba(235, 160, 190, 0.8));

}

#options_button::before, 
#send_but::before, 
#extensionsMenuButton::before {
    display: none;
}

#quick-reply-rocket-button > i {
    display: none;
}

#options_button, 
#send_but, 
#extensionsMenuButton, 
#quick-reply-rocket-button {
    width: 41px;
    height: 41px;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    font-size: 0;
    opacity: 1 !important;
    position: relative;
    top: 3px;
    border: none;
    background-color: transparent;
    box-shadow: none;
    padding: 0;
    margin: 0 2px;
    transition: all 0.3s ease-in-out;
    filter: drop-shadow(1px 1px 0px rgba(255, 182, 193, 0.6));
}

/* 图片 */
#options_button,#extensionsMenuButton { 
    background-image: url('https://iili.io/fDy8b5P.png');background-size: 32px !important; 
}
#quick-reply-rocket-button,#send_but { 
    background-image: url('https://iili.io/fyFDkj1.png');
}
/* 停止 */
#mes_stop {
    font-size: 0;
    width: 38px;
    height: 38px;
    background-image: url('https://iili.io/fmIX2LP.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    opacity: 1;
}

.last_mes {
  margin-bottom: 5px;
}

/* 输入框高度 */
#send_textarea:placeholder-shown {
    height: 30px;
}
/*拓展隐藏*/
textarea::-webkit-resizer {
    background-color: transparent; 
    background-image: none;        
    border: none;                  
}

textarea {
    resize: vertical; 
}
/* 自定义输入框提示词@墨千尾 */
#nonQRFormItems {
    position: relative; 
}
#send_textarea::placeholder {
    color: transparent !important; 
    text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "₊ ⊹❀流水落花春去也";
    position: absolute;
    top: 50%;
    left: 53%;
    transform: translate(-50%, -50%); font-family: "Zhi Mang Xing";
    font-size: 0.9rem;color: rgba(255, 182, 193, 0.6)!important;  
    pointer-events: none; 
    z-index: 10;
    width: 70%; 
    text-align: center;
    white-space: nowrap;   
}

/* qr隐藏@twelve.+@dengdeng */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}

/* 背景 */
.drawer-content {
    background-image: url('https://iili.io/ftQZcKu.png');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

}
/*图片全屏@NARAKI*/
.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize));*/
}
#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

@media (max-width: 600px) {
    #right-nav-panel {
        max-height: calc(100dvh - var(--topBarBlockSize));
    }
}
/*滑动*/
input[type="range"].neo-range-slider,
input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 95.5% !important; 
  margin: 15px auto !important; 
  display: block !important;
  background: transparent !important; 
  border: none !important;
  box-shadow: none !important; 
  outline: none !important;
  filter: none !important; 
  opacity: 1 !important;
  mix-blend-mode: normal !important;
  color-scheme: light !important;
}

input[type="range"].neo-range-slider::-webkit-slider-runnable-track,
input[type="range"]::-webkit-slider-runnable-track {
  height: 6px !important; 
  border-radius: 6px !important;
  background: linear-gradient(to right, rgba(255, 200, 215, 0.8), rgba(255, 250, 252, 1)) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  box-shadow: inset 0 1px 2px rgba(255, 255, 255, 1), 0 0 5px rgba(255, 182, 193, 0.6) !important;
  filter: none !important;
  opacity: 1 !important;
}

input[type="range"].neo-range-slider::-webkit-slider-thumb,
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 40px !important;
  height: 40px !important;
  background: url('https://iili.io/fDypysR.png') no-repeat center !important;
  background-size: contain !important;
  cursor: pointer !important;
  border: none !important; 
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: drop-shadow(0 2px 4px rgba(221, 107, 140, 0.3)) !important; 
  opacity: 1 !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
  margin-top: -17px !important; 
}



/* 聊天气泡 */
.mes {
    width: 100% !important;
    max-width: 100% !important;
    margin: 75px auto auto auto !important;
    padding: 190px 23px 180px 23px !important;   
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;   
    background-image: url("https://iili.io/fDjxYnp.png");
    background-position: center top;
    background-repeat: repeat-y;
    background-size: 100% auto;
    overflow: visible !important;
}

/* 上 */
.mes::before {
    content: '';
    position: absolute;
    top: -27px;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url("https://iili.io/fpLYgAQ.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center top;
    z-index: -1;
}

/* 下 */
.mes::after {
    content: '';
    position: absolute;
    bottom:-7px;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url("https://iili.io/fDjxjol.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center bottom;
    z-index: -1;
}
/* 文本 */
.mes_block {
    position: relative;
    isolation: isolate;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;overflow: visible !important;top: 100px !important; 
}

.mes_block .ch_name,
.mes_block .mes_text {
    width: 100%;
    box-sizing: border-box;
    margin: 0;
}

/* 文字 */
.mes_text {
    line-height: 1.6 !important;
    letter-spacing: 0.5px;
    word-break: break-word;    
    text-align: justify;
    font-weight: 500; position: relative !important;
    top: -48px !important;   
}
.mes[mesid="0"] .mes_text {padding-top: 19px !important;}
/*文字铺满@墨千尾*/
.mes .mes_text {
    width: 100%;
margin: 0;
}
/* 素白 */
.mes .mes_text {
    color: #4b2e36;
    background: rgba(255, 255, 255, 0.5) !important; 
    padding: 10px;z-index: -1; 
    border-radius: 1px !important; 
    backdrop-filter: blur(4px) !important; 
}

/* 气泡布局 */
#chat {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-left: 0 !important;
}

#chat .mes {
    top: -57px;
    bottom: 0px;
}

#chat .mes:first-child {
    top: -30px !important;
}
/*删除消息*/
.mes.selected {
    background-color: rgba(255, 80, 80, 0.15) !important;
    border: 2px solid #FF5050 !important;
    box-shadow: 0 0 15px rgba(255, 80, 80, 0.4) !important;
}
/* ♪头像&头像框 */
.mes .mesAvatarWrapper {
    position: absolute;
    display: flex;
    z-index: 5;
    padding: 0;
    width: auto;
}

/* ♪头像尺寸@blue */
.mes .mesAvatarWrapper {
    width: 193px !important;  
    height: 193px !important; 
}
.mesAvatarWrapper .avatar {
    --avatar-base-width: 193px;
    --avatar-base-height: 193px;
    width: 193px !important;  
    height: 193px !important; 
    position: relative;
}

.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;

    z-index: 1;
    box-shadow: none !important;
}

/* ♪头像整体位置 */
.mes .mesAvatarWrapper {
    top: 9px;
    right: -18.6%;
    transform: translateX(-50%);
}
/*樱枝雪*/
.mes .mesAvatarWrapper::after {
    content: '';
    position: absolute;
    z-index: 1;
    pointer-events: none;    
    top: 50%;
    left: 50%;
    transform: translate(-46%, -50%);    
    width: 121%;
    height: 121%;   
    background-image: url("https://iili.io/fyHcZlf.png");
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}
/*遮罩*/
.mes .avatar img {
    -webkit-mask-image: url("https://iili.io/fyHYRUl.png");
    mask-image: url("https://iili.io/fyHYRUl.png");
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
}
/* 三元素 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    position: absolute ;
    z-index: 20 ;    
    font-size: 12px ;font-family: "Huiwen-mincho";   
    white-space: nowrap ;    
    pointer-events: none;
    top: 96.6% ;
    left: 50%;
}
/* ID */
.mes .mesIDDisplay {
    transform: translateX(-45px); 
}
/* Timer */
.mes .mes_timer {
    transform: translateX(15px);
}
/* Token */
.mes .tokenCounterDisplay {
    transform: translateX(81px);
}
/* 名字&时间戳 */
.mes .ch_name {
    position: absolute ;
    writing-mode: vertical-rl ;
    top: -70px ;
    left: 15px ;
    white-space: nowrap ;
    font-size: 18px ;
    font-family: "QuanHengDuLiang";
     font-weight: normal;color: rgba(127, 84, 104,0.7 ) ;
    user-select: none ;line-height: 1 !important; 
}

.mes .ch_name::after {
    content: attr(ch_name) !important;  
}

.mes .ch_name::before {
    content: "  " ;
    writing-mode: horizontal-tb ;
    position: absolute ;
    top: 0px ;
    right: 16px ;
    font-size: 8px ;
    line-height: 1 !important; 
}
.mes .timestamp {
    position: absolute ;
    writing-mode: horizontal-tb ;
    top: 0px ;
    left: 64% ; 
    transform: translateX(-50%); 
    font-size: 14px ;
    font-family: "Huiwen-mincho" ;
    font-style: italic;
    color: #b2a1a1 ;line-height: 1 !important; 
}
/* 首字 */
.mes .ch_name .name_text::first-letter {
  font-size: 1.2em;  
}
/*编辑&更多*/
.mes .mes_edit_buttons {
    position: absolute ; 
    writing-mode: horizontal-tb ;
    gap: 5px ;
    bottom: 19px ; 
    left: 5% ; 
    transform: translateX(-30px); 
    filter: drop-shadow(0px 0px 0px rgba(221, 107, 140, 0.5)); z-index: 20 ;
}

.mes .mes_edit_buttons[style*="display: block"],
.mes .mes_edit_buttons[style*="display: inline"] {
    display: flex ;
    flex-direction: row ;
}

.mes .mes_edit, 
.mes .extraMesButtonsHint {
    position: relative ;
    opacity: 1 ;
    width: 25px ;
    height: 25px ;right: -3px ; 
    padding: 0 ;
    margin: 0 ;  
    font-size: 0 !important; 
    filter: drop-shadow(0px 0px 0px rgba(221, 107, 140, 1)) !important;   
}
.mes .mes_edit::before, 
.mes .extraMesButtonsHint::before {
    content: '' ;
    display: block;
    width: 100% ;
    height: 100% ;
    background-image: url('https://iili.io/fDypysR.png');
    background-size: contain ;
    background-repeat: no-repeat ;
    background-position: center ;
}

.mes .mes_edit_buttons .menu_button {
    position: relative ;
    width: 28px ;
    height: 28px ; 
    border-radius: 40% !important;   
    box-shadow: 0 2px 4px rgba(221, 107, 140, 0.2) ;
    opacity: 1 ;
    margin: 0 ;
}

/*思维链*/
.mes_reasoning_details {
    position: relative ;
    overflow: visible ;
}
.mes_reasoning_header {
    background: url("https://iili.io/fyp5dI2.png") no-repeat center center ;
    background-size: contain ;   
    position: absolute ;
    top: -158px ;
    right: -90px ;
    width: 125px ;
    height: 125px ;
    margin: 0 ;
    z-index: 99 ;
}

.mes_reasoning_header * {
    display: none !important;
}

.mes_reasoning_details:not([open]) .mes_reasoning_actions {
    display: none !important;
}

.mes_reasoning_details[open] .mes_reasoning_actions {
    display: flex ;
    position: absolute ;
    top: 29px ;
    right: 5px ;         
    z-index: 200 ;                 
}

.mes_reasoning_actions div, 
.mes_reasoning_actions i {                     
    filter: none !important;   
}

/*左右箭头@NARAKI*/
.swipe_left, .swipe_right {
    background-image: url('https://iili.io/fDyyHfp.png') ;
    background-size: contain ;
    background-repeat: no-repeat ;
    background-position: center ;   
    font-size: 0 ;    
    width: 28px ;  
    height: 28px ;    
    opacity: 1 ;    
}

/* 左箭头 */
.swipe_left {
    position: absolute ;
    left: auto ;
    bottom: 20px ; 
    right: 62px ;        
    }

.swipeRightBlock {
  margin-right: 20px ; 
margin-bottom: 20px ; 
}
/* 右箭头 */
.swipe_right {
    position: relative ; 
    bottom: -20px ;right: -19px ; 
}

/* 数字 */
.swipes-counter {
    transform: translateX(-20%);  
    font-family: "Huiwen-mincho" ; 
    font-size: 14px ;
    color: rgba(127, 84, 104, 0.8);    
}
/* 预设 */
#completion_prompt_manager,
#completion_prompt_manager_list {
  display: flex;
  flex-direction: column;
  background: linear-gradient(145deg, rgba(255, 252, 253, 0.9) 0%, rgba(255, 240, 245, 0.8) 100%) ;
  backdrop-filter: blur(15px) saturate(120%) ;
  border: 1px solid rgba(255, 255, 255, 0.9) ;
  border-radius: 16px;
  box-shadow: 
    0 8px 32px rgba(235, 168, 189, 0.15),
    inset 0 0 15px rgba(255, 255, 255, 0.8) ;
}
.completion_prompt_manager_prompt {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 235, 240, 0.6) 100%) ;
  border-radius: 14px;
  border: 1.5px solid rgba(255, 210, 225, 0.8) !important;  
  padding: 8px;
  backdrop-filter: blur(5px) !important;
  box-shadow: 0 4px 10px rgba(220, 160, 180, 0.1)
}
.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background: rgba(245, 240, 242, 0.6) ;
  border-radius: 14px;
  border: 1px dashed rgba(200, 180, 190, 0.5) !important; 
  padding: 8px;
  backdrop-filter: blur(5px);
  opacity: 0.7;
}
.completion_prompt_manager_prompt .prompt-manager-inspect-action {
    color: #8e5e6a ; 
    font-weight: bold;   
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
